function gameOverFromChess(chess) {
  return chess.isGameOver();
}
function isPlayersTurn(player, lobby) {
  const chess = new Chess();
  chess.load(lobby.latest_match_state);
  const isCreator = lobby.lobby_creator === player;
  const playerColor = isCreator === lobby.player_one_iswhite ? "w" : "b";
  return chess.turn() === playerColor;
}
function updateBoard(fenBoard, move) {
  const chess = new Chess();
  chess.load(fenBoard);
  chess.move(move);
  return chess.fen();
}

// ../game-logic/build/tick.js
function processTick(matchEnvironment, matchState, moves, currentTick, __) {
  const move = moves[currentTick - 1];
  const chess = new Chess();
  if (!move || !move.move_pgn || gameOverFromChess(chess))
    return null;
  const event = {
    user: move.wallet,
    pgn_move: move.move_pgn
  };
  applyEvents(matchState, event);
  return [event];
}
function applyEvents(matchState, event) {
  const newBoard = updateBoard(matchState.fenBoard, event.pgn_move);
  matchState.fenBoard = newBoard;
}

